// Junta lo que trajo Google en un texto corto para el modelo
// y guarda los tres primeros enlaces para la página.
const r = $input.first().json
const form = $('Formulario').first().json
const lista = (r.organic_results || []).slice(0, 6)
const renglones = lista.map(function (x, i) {
  return (i + 1) + '. ' + x.title + ' (' + (x.source || x.link) + '): ' + (x.snippet || '')
})
return [{
  json: {
    nombre: form.nombre.trim(),
    idea: (form.idea || '').trim(),
    cantidad: lista.length,
    resultados: renglones.length ? renglones.join('\n') : 'Google no encontró nada con ese nombre exacto.',
    enlaces: lista.slice(0, 3).map(function (x) { return { titulo: x.title, enlace: x.link } })
  }
}]

// Arma la página del veredicto con lo que dijo el modelo y los enlaces de Google.

// Todo texto que viene de afuera pasa por acá antes de entrar al HTML.
function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}
// Solo enlaces web de verdad.
function enlaceSeguro(url) {
  return /^https?:\/\//i.test(String(url || '')) ? String(url) : ''
}
// Busca una línea del estilo CLAVE: valor en la respuesta del modelo.
function linea(texto, clave) {
  const m = texto.match(new RegExp(clave + '\\s*:\\s*(.+)', 'i'))
  return m ? m[1].trim() : ''
}
// Estilos de la charla. Una regla por propiedad, así no hace falta separarlas.
function css(reglas) {
  return Object.keys(reglas).map(function (sel) {
    return Object.keys(reglas[sel]).map(function (prop) {
      return sel + '{' + prop + ':' + reglas[sel][prop] + '}'
    }).join('')
  }).join('')
}
const estilo = css({
  'html, body': { 'background': '#070A0F', 'margin': '0' },
  'body': { 'color': '#F5F7FF', 'font-family': '"Segoe UI", system-ui, sans-serif', 'font-weight': '700', 'font-size': '22px', 'line-height': '1.4', 'display': 'block' },
  '.tarjeta': { 'max-width': '720px', 'margin': '0 auto', 'padding': '48px 24px' },
  '.tarjeta p': { 'margin': '0 0 16px 0', 'font-size': '22px' },
  '.tarjeta .rotulo': { 'color': '#9AA3B8', 'margin': '32px 0 8px 0' },
  '.tarjeta h1': { 'font-size': '56px', 'line-height': '1.1', 'margin': '8px 0 0 0', 'overflow-wrap': 'anywhere' },
  '.tarjeta .veredicto': { 'font-size': '64px', 'letter-spacing': '2px', 'margin': '16px 0' },
  '.tarjeta .libre': { 'color': '#FFB547' },
  '.tarjeta .ocupado': { 'color': '#FF7A7A' },
  '.tarjeta .dudoso': { 'color': '#9AA3B8' },
  '.tarjeta .otros': { 'color': '#FFB547', 'font-size': '28px' },
  '.tarjeta ul': { 'margin': '0', 'padding': '0 0 0 28px' },
  '.tarjeta li': { 'margin': '0 0 12px 0' },
  '.tarjeta a': { 'color': '#4DA3FF' }
})

const datos = $('Resumir resultados').first().json
const texto = String($input.first().json.text || '').replace(/\*/g, '')
let veredicto = linea(texto, 'VEREDICTO').toUpperCase().replace(/[^A-ZÁÉÍÓÚ]/g, '')
if (['LIBRE', 'OCUPADO', 'DUDOSO'].indexOf(veredicto) === -1) veredicto = 'DUDOSO'
const porque = linea(texto, 'POR QU[ÉE]')
const otros = linea(texto, 'OTROS NOMBRES').split(',').map(function (x) { return x.trim().replace(/\.$/, '') }).filter(Boolean).slice(0, 3)
const enlaces = datos.enlaces.filter(function (e) { return enlaceSeguro(e.enlace) }).map(function (e) {
  return '<li><a href="' + esc(enlaceSeguro(e.enlace)) + '" target="_blank" rel="noopener">' + esc(e.titulo) + '</a></li>'
}).join('')
const html = '<style>' + estilo + '</style>' +
  '<main class="tarjeta">' +
  '<p class="rotulo">¿Ya existe tu nombre?</p>' +
  '<h1>' + esc(datos.nombre) + '</h1>' +
  '<p class="veredicto ' + esc(veredicto.toLowerCase()) + '">' + esc(veredicto) + '</p>' +
  '<p>' + esc(porque) + '</p>' +
  (otros.length ? '<p class="rotulo">Otros nombres</p><p class="otros">' + otros.map(esc).join(' / ') + '</p>' : '') +
  (enlaces ? '<p class="rotulo">Lo que encontró Google</p><ul>' + enlaces + '</ul>' : '') +
  '</main>'
return [{ json: { html: html, veredicto: veredicto, por_que: porque, otros_nombres: otros } }]
